Tool response:
Tool: add_shipment_service
Description: Requests a service such as liftgate delivery, inside delivery, or signature required for a shipment.
Parameters:
    {
      "type": "object",
      "properties": {
        "shipment_id": {
          "type": "integer",
          "description": "Internal ID of the shipment to add service to",
          "title": "Shipment Id"
        },
        "service_type": {
          "type": "string",
          "title": "Service Type",
          "description": "Type of service to add (liftgate_delivery, inside_delivery, signature_required, residential_delivery)"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes",
          "description": "Optional notes about the service request"
        }
      },
      "required": [
        "shipment_id",
        "service_type"
      ]
    }

Tool response:
Tool: reroute_shipment
Description: Creates a reroute request for a shipment that matches the admin rule 
'flag all residential deliveries >50 lbs for liftgate request'.
Parameters:
    {
      "type": "object",
      "properties": {
        "shipment_id": {
          "type": "integer",
          "description": "Internal ID of the shipment to reroute",
          "title": "Shipment Id"
        },
        "reason": {
          "type": "string",
          "title": "Reason",
          "description": "Reason for requesting the reroute"
        }
      },
      "required": [
        "shipment_id",
        "reason"
      ]
    }

Tool response:
Tool: get_shipment_evaluation
Description: Fetches the evaluation result of a shipment against active admin rules.
Specifically checks if it matches the rule 'flag all residential deliveries >50 lbs for liftgate request'.
Parameters:
    {
      "type": "object",
      "properties": {
        "shipment_id": {
          "type": "integer",
          "description": "Internal ID of the shipment to evaluate",
          "title": "Shipment Id"
        }
      },
      "required": [
        "shipment_id"
      ]
    }

Tool response:
Tool: get_shipment_services
Description: Retrieves all services currently associated with a shipment.
Parameters:
    {
      "type": "object",
      "properties": {
        "shipment_id": {
          "type": "integer",
          "description": "Internal ID of the shipment to retrieve services for",
          "title": "Shipment Id"
        }
      },
      "required": [
        "shipment_id"
      ]
    }
